-- 1) '상시 접수' 부제 제거 (요청: 상단 코멘트 삭제)
UPDATE public.events SET subtitle = NULL WHERE slug = '2026' AND subtitle = '상시 접수';

-- 2) 사번 기반 접근 제어를 위한 임직원 사번 테이블
-- 주의: anon/authenticated 권한을 부여하지 않고 RLS만 켜 둔 상태이므로
-- 이 테이블은 서비스 롤(서버 전용 supabaseAdmin)로만 조회할 수 있습니다.
-- 클라이언트 번들에는 사번 목록이 절대 포함되지 않습니다.
CREATE TABLE public.authorized_employees (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_no text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.authorized_employees ENABLE ROW LEVEL SECURITY;
-- anon/authenticated 에게는 어떤 정책도 부여하지 않습니다 (완전 비공개).
GRANT ALL ON public.authorized_employees TO service_role;

-- 3) 2026-08-10 임직원 명부 기준 사번 시드 데이터 (4011건)
ON CONFLICT (employee_no) DO NOTHING;
